        assertEquals(-1,test.getYears());
        assertEquals(-2,test.getMonths());
        assertEquals(-3,test.getWeeks());
        assertEquals(-4,test.getDays());
        assertEquals(-5,test.getHours());
        assertEquals(-6,test.getMinutes());
