public void test_subtract_oe() throws Exception {
        DurationField fld = ISOChronology.getInstanceUTC().millis();
        assertEquals(900,fld.subtract(1000L,100));
        assertEquals(900L,fld.subtract(1000L,100L));
        assertEquals((1000L - Integer.MAX_VALUE),fld.subtract(1000L,Integer.MAX_VALUE));
        assertEquals((1000L - Integer.MIN_VALUE),fld.subtract(1000L,Integer.MIN_VALUE));
        assertEquals((1000L - Long.MAX_VALUE),fld.subtract(1000L,Long.MAX_VALUE));
        try {
            fld.subtract(-1000L, Long.MIN_VALUE);
            fail();
        } catch (ArithmeticException ex) {}
    }

public void testPropertyAddToCopyYear_oe() {
        LocalDate test = new LocalDate(1972, 6, 9);
        LocalDate copy = test.year().addToCopy(9);
        check(test, 1972, 6, 9);
        check(copy, 1981, 6, 9);

        copy = test.year().addToCopy(0);
        check(copy, 1972, 6, 9);

        copy = test.year().addToCopy(292278993 - 1972);
        check(copy, 292278993, 6, 9);

        try {
            test.year().addToCopy(292278993 - 1972 + 1);
            fail();
        } catch (IllegalArgumentException ex) {}
        check(test, 1972, 6, 9);

        copy = test.year().addToCopy(-1972);
        check(copy, 0, 6, 9);

        copy = test.year().addToCopy(-1973);
        check(copy, -1, 6, 9);

        try {
            test.year().addToCopy(-292275054 - 1972 - 1);
            fail();
        } catch (IllegalArgumentException ex) {}
        check(test, 1972, 6, 9);
    }

